insert into ejercicios (id, leccion_id, orden, tipo, datos, tema_id, pata, reservado) values
  ('ep3-presente-progresivo-01', 'ep3-presente-progresivo', 1, 'elegir', $j${"frase": "I ___ working right now.", "opciones": ["am", "is", "are"], "correcta": 0, "es": "Estoy trabajando ahora mismo.", "explicacion": "I → am."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-02', 'ep3-presente-progresivo', 2, 'elegir', $j${"frase": "She ___ watching TV in the living room.", "opciones": ["is", "are", "does"], "correcta": 0, "es": "Ella está viendo televisión en la sala.", "explicacion": "She → is."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-03', 'ep3-presente-progresivo', 3, 'elegir', $j${"frase": "We ___ having lunch at the moment.", "opciones": ["are", "is", "do"], "correcta": 0, "es": "Estamos almorzando en este momento.", "explicacion": "We → are."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-04', 'ep3-presente-progresivo', 4, 'elegir', $j${"frase": "I'm not ___ now. I'm reading.", "opciones": ["sleep", "sleeping", "sleeps"], "correcta": 1, "es": "No estoy durmiendo ahora. Estoy leyendo.", "explicacion": "Verbo + -ing: sleeping."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-05', 'ep3-presente-progresivo', 5, 'escribir', $j${"respuestas": ["my wife is selling shoes on tiktok now", "my wife is selling shoes on tiktok right now", "my wife is selling shoes on tiktok at the moment"], "mostrar": "My wife is selling shoes on TikTok now.", "es": "Mi esposa está vendiendo zapatos en TikTok ahora.", "explicacion": "is + selling (sell → selling)."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-06', 'ep3-presente-progresivo', 6, 'ordenar', $j${"frase": "Are you studying English now?", "es": "¿Estás estudiando inglés ahora?", "explicacion": "Pregunta: Are + sujeto + verbo-ing?"}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-07', 'ep3-presente-progresivo', 7, 'emparejar', $j${"pares": [["I am working", "estoy trabajando"], ["she is sleeping", "ella está durmiendo"], ["we are eating", "estamos comiendo"], ["they are playing", "ellos están jugando"]], "es": "", "explicacion": "am/is/are + verbo con -ing = pasa ahora."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', false),
  ('ep3-presente-progresivo-08', 'ep3-presente-progresivo', 8, 'escuchar', $j${"opciones": ["He is running now.", "He runs every day.", "He ran yesterday."], "correcta": 0, "audio": "He is running now.", "es": "Él está corriendo ahora.", "explicacion": "is running = está corriendo ahora."}$j$::jsonb, 'ep3-presente-progresivo', 'input', false),
  ('banco-ep3-ep3-presente-progresivo-01', 'banco-ep3', 30, 'comprension', $j${"modo": "escuchar", "lineas": [{"en": "Hi Ana! Where are you?", "es": "¡Hola Ana! ¿Dónde estás?"}, {"en": "I'm at the store. I'm helping my wife.", "es": "Estoy en la tienda. Estoy ayudando a mi esposa."}, {"en": "She is taking photos of the new shoes.", "es": "Ella está tomando fotos de los zapatos nuevos."}], "pregunta": "What is the wife doing?", "pregunta_es": "¿Qué está haciendo la esposa?", "opciones": ["She is taking photos.", "She is sleeping.", "She is driving."], "correcta": 0, "explicacion": "is taking = está tomando."}$j$::jsonb, 'ep3-presente-progresivo', 'input', false),
  ('banco-ep3-ep3-presente-progresivo-02', 'banco-ep3', 31, 'comprension', $j${"modo": "leer", "lineas": [{"en": "It's 9 a.m. My daughter is watching a cartoon.", "es": "Son las 9 a.m. Mi hija está viendo una caricatura."}, {"en": "My son is eating his breakfast.", "es": "Mi hijo está desayunando."}, {"en": "I'm working on my computer.", "es": "Estoy trabajando en mi computador."}], "pregunta": "What is the son doing?", "pregunta_es": "¿Qué está haciendo el hijo?", "opciones": ["He is eating breakfast.", "He is sleeping.", "He is working."], "correcta": 0, "explicacion": "is eating = está comiendo."}$j$::jsonb, 'ep3-presente-progresivo', 'input', false),
  ('banco-ep3-ep3-presente-progresivo-03', 'banco-ep3', 32, 'decir', $j${"es": "Estoy escribiendo un mensaje ahora.", "respuestas": ["i am writing a message now", "im writing a message now", "i am writing a message right now", "im writing a message right now"], "mostrar": "I'm writing a message now.", "explicacion": "write → writing (se quita la e final)."}$j$::jsonb, 'ep3-presente-progresivo', 'output', false),
  ('banco-ep3-ep3-presente-progresivo-04', 'banco-ep3', 33, 'decir', $j${"es": "Mi hija está durmiendo.", "respuestas": ["my daughter is sleeping", "my daughter is sleeping now"], "mostrar": "My daughter is sleeping.", "explicacion": "sleep → sleeping = durmiendo."}$j$::jsonb, 'ep3-presente-progresivo', 'output', false),
  ('banco-ep3-ep3-presente-progresivo-05', 'banco-ep3', 34, 'libre', $j${"pregunta": "What are you doing right now? Write two sentences with the present progressive.", "pregunta_es": "¿Qué estás haciendo ahora? Escribe dos frases con presente progresivo.", "ejemplo": "I'm reading this lesson. My wife is working in the store.", "criterio": "am/is/are + verbo con -ing para algo que pasa ahora.", "explicacion": "am/is/are + verbo con -ing para algo que pasa ahora."}$j$::jsonb, 'ep3-presente-progresivo', 'output', false),
  ('banco-ep3-ep3-presente-progresivo-06', 'banco-ep3', 35, 'rapido', $j${"frase": "I ___ studying now.", "opciones": ["am", "is"], "correcta": 0, "es": "Estoy estudiando ahora.", "explicacion": "I → am.", "segundos": 6}$j$::jsonb, 'ep3-presente-progresivo', 'fluidez', false),
  ('banco-ep3-ep3-presente-progresivo-07', 'banco-ep3', 36, 'rapido', $j${"frase": "They ___ working today.", "opciones": ["are", "is"], "correcta": 0, "es": "Ellos están trabajando hoy.", "explicacion": "They → are.", "segundos": 6}$j$::jsonb, 'ep3-presente-progresivo', 'fluidez', false),
  ('banco-ep3-ep3-presente-progresivo-08', 'banco-ep3', 37, 'rapido', $j${"frase": "work → ___ (trabajando)", "opciones": ["working", "workking"], "correcta": 0, "es": "", "explicacion": "work + ing = working.", "segundos": 6}$j$::jsonb, 'ep3-presente-progresivo', 'fluidez', false),
  ('examen-ep3-ep3-presente-progresivo-01', 'examen-ep3', 10, 'elegir', $j${"frase": "Look! It ___ raining.", "opciones": ["is", "are", "do"], "correcta": 0, "es": "¡Mira! Está lloviendo.", "explicacion": "It → is."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', true),
  ('examen-ep3-ep3-presente-progresivo-02', 'examen-ep3', 11, 'escribir', $j${"respuestas": ["she is cooking lunch", "shes cooking lunch", "she is cooking the lunch"], "mostrar": "She's cooking lunch.", "es": "Ella está cocinando el almuerzo.", "explicacion": "cook → cooking."}$j$::jsonb, 'ep3-presente-progresivo', 'estudio', true),
