  ('banco-ep3-ep3-pasatiempos-02', 'banco-ep3', 39, 'comprension', $j${"modo": "leer", "lineas": [{"en": "My hobbies are music and movies.", "es": "Mis pasatiempos son la música y las películas."}, {"en": "I like listening to music every night.", "es": "Me gusta escuchar música cada noche."}], "pregunta": "What does he like to do at night?", "pregunta_es": "¿Qué le gusta hacer de noche?", "opciones": ["Listen to music.", "Play soccer.", "Go running."], "correcta": 0, "explicacion": "like + -ing: listening to music."}$j$::jsonb, 'ep3-pasatiempos', 'input', false),
