  ('banco-ep3-ep3-pasatiempos-05', 'banco-ep3', 42, 'libre', $j${"pregunta": "What are your hobbies? Use I like + -ing.", "pregunta_es": "¿Cuáles son tus pasatiempos? Usa I like + -ing.", "ejemplo": "I like reading and going running on Sundays.", "criterio": "like + verbo con -ing.", "explicacion": "like + verbo con -ing."}$j$::jsonb, 'ep3-pasatiempos', 'output', false),
