  ('ep3-ordenes-avisos-02', 'ep3-ordenes-avisos', 2, 'elegir', $j${"frase": "___ your shoes, please.", "opciones": ["Take off", "Takes off", "Taking off"], "correcta": 0, "es": "Quítate los zapatos, por favor.", "explicacion": "take off = quitar."}$j$::jsonb, 'ep3-ordenes-avisos', 'estudio', false),
