  ('banco-ep3-ep3-ordenes-avisos-01', 'banco-ep3', 46, 'comprension', $j${"modo": "escuchar", "lineas": [{"en": "Teacher: Sit down and wait, please.", "es": "Profesora: Siéntense y esperen, por favor."}, {"en": "Teacher: Don't open your books yet.", "es": "Profesora: No abran sus libros todavía."}], "pregunta": "What does the teacher ask?", "pregunta_es": "¿Qué pide la profesora?", "opciones": ["To sit down and wait.", "To leave the room.", "To read a book."], "correcta": 0, "explicacion": "Sit down and wait = siéntense y esperen."}$j$::jsonb, 'ep3-ordenes-avisos', 'input', false),
